/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />

/**
 * Files — Corpus Lifecycle (code-first journey; no Epic, shipped behavior is the
 * bar). Covers the corpus as an object: list, create, navigate, edit, delete —
 * the cheapest surface in the vertical (no feature flag, no seeded state, no
 * LLM). Walks C1–C12 of the journey's test spine. The flag-gated `/workspace`
 * tile grid (C13–C14) is deliberately out of scope here.
 *
 * Surfaces: `routes/CorpusList` (`/files`), `routes/CorpusCreate` (`/files/new`),
 * `components/EditCorpusModal`, `components/ConfirmDeleteModal`.
 *
 * Persona: P2 (org owner). Do NOT write a viewer variant expecting fewer
 * buttons — `useCapabilities` grants corpus_edit/corpus_delete to any
 * authenticated session (GAP-11); a permission assertion here would have to
 * assert the BFF's response, not the button's presence.
 *
 * DOM traps this file navigates:
 *  - The corpus NAME cell is rendered raw (`data-i18n-allow="data"`), so
 *    `findByText(name)` is an exact, unwrapped match and is the reliable row
 *    anchor. The row aria-labels and the toast strings interpolate the name and
 *    ARE Paraglide-wrapped (U+2066/U+2069 isolate marks), so they are NOT
 *    matched by text — rows are reached via the name cell + the stable
 *    `[data-row-action]` buttons, and toasts via `[data-testid="toast-*"]`.
 *  - Edit modal is a Radix Dialog (`role="dialog"`); the delete modal is an
 *    AlertDialog (`role="alertdialog"`). Both confirm buttons use NATIVE
 *    `disabled` (so `be.disabled` is correct here, unlike the suite's usual
 *    aria-disabled convention).
 *  - Empty / list-error / create-error states are driven by stubbing the
 *    response (you can't force the real BFF to 500). Every CRUD happy path uses
 *    the REAL BFF and round-trips through a list refetch — the proof the server
 *    kept the change, not just client state.
 */

import {
  bffCreateCorpus,
  bffDeleteCorpus,
  requireFilesUp,
  uniq,
  visitFiles,
} from "./_helpers";

/** Matches the corpus LIST endpoint (`/corpora` or `/corpora?…`) but not
 *  `/corpora/{id}` or `/workspace/corpora`. */
const CORPORA_LIST = /\/api\/v1\/files\/corpora(\?|$)/;

/** The row (`<tr>`) for a corpus, anchored by its unwrapped name cell. */
function corpusRow(name: string): Cypress.Chainable<JQuery<HTMLTableRowElement>> {
  return cy.findByText(name).closest("tr");
}

describe("files: corpus lifecycle (#files code-first)", () => {
  /** Corpora seeded (or UI-created) by a test, torn down after it. */
  let cleanup: string[] = [];

  beforeEach(function () {
    cy.login("P2");
    requireFilesUp(this);
  });

  afterEach(() => {
    cleanup.forEach((id) => bffDeleteCorpus(id));
    cleanup = [];
  });

  // ── C2 — empty state ───────────────────────────────────────────────────────
  it("renders the empty state (not an empty table) when the org has no corpora", () => {
    cy.intercept("GET", CORPORA_LIST, {
      statusCode: 200,
      body: { data: { corpora: [], next_cursor: "" } },
    }).as("listCorpora");

    visitFiles("/files");
    cy.wait("@listCorpora");

    cy.findByText("No corpora yet — create one to get started.").should(
      "be.visible",
    );
    cy.get("table").should("not.exist");
  });

  // ── C3 — list error ────────────────────────────────────────────────────────
  it("renders an alert (and no table) when the corpus list fails to load", () => {
    cy.intercept("GET", CORPORA_LIST, {
      statusCode: 500,
      body: { error: { code: "internal", message: "Simulated list failure" } },
    }).as("listCorpora");

    visitFiles("/files");
    cy.wait("@listCorpora");

    cy.findByRole("alert").should("contain.text", "Simulated list failure");
    cy.get("table").should("not.exist");
  });

  // ── C1 + C4 + C5 — the row: render, click-to-open, keyboard ─────────────────
  it("shows a corpus row and opens it by click and by Enter, while action buttons run their own handler", () => {
    const name = uniq("Corpus Row");
    bffCreateCorpus({ name, visibility: "PRIVATE" }).then((corpus) => {
      cleanup.push(corpus.id);
      visitFiles("/files");

      // C1: name, PRIVATE pill, and a created date all render on the row.
      corpusRow(name).within(() => {
        cy.findByText(name).should("be.visible");
        cy.findByText("Private").should("be.visible");
      });

      // C4/C5 (negative): activating an ACTION button runs its own handler and
      // does NOT navigate the row — the delete button's onClick stops
      // propagation, so it opens the confirm modal and we stay on the list. We
      // click rather than synth-Enter here: a real activation is a click (the
      // stopPropagation is the guard under test), and a synthetic keydown on a
      // button isn't a faithful activation path.
      corpusRow(name).find('[data-row-action="delete"]').click();
      cy.findByRole("alertdialog").should("be.visible");
      cy.location("pathname").should("match", /\/files\/?$/);
      // Dismiss so the modal doesn't shadow the nav assertions below.
      cy.findByRole("alertdialog")
        .findByRole("button", { name: "Cancel" })
        .click();
      cy.findByRole("alertdialog").should("not.exist");

      // C5 (positive): Enter on the focused ROW navigates to the corpus.
      corpusRow(name).focus().trigger("keydown", { key: "Enter" });
      cy.location("pathname").should("include", `/corpora/${corpus.id}`);

      // C4 (positive): a plain click on the row (its name cell) navigates too.
      visitFiles("/files");
      corpusRow(name).findByText(name).click();
      cy.location("pathname").should("include", `/corpora/${corpus.id}`);
    });
  });

  // ── C6 — create form validation ─────────────────────────────────────────────
  it("keeps Create disabled until the name is valid, and shows a field error on blur", () => {
    visitFiles("/files/new");

    cy.findByRole("heading", { name: "Create corpus" }).should("be.visible");
    cy.get("form").find('button[type="submit"]').should("be.disabled");

    // Blurring an empty name surfaces the field error and marks it invalid.
    cy.findByLabelText("Name").focus().blur();
    cy.findByLabelText("Name").should("have.attr", "aria-invalid", "true");
    cy.get("#corpus-create-name-error").should("exist");

    // A valid name clears the error and enables submit.
    cy.findByLabelText("Name").type(uniq("Valid")).blur();
    cy.findByLabelText("Name").should("have.attr", "aria-invalid", "false");
    cy.get("form").find('button[type="submit"]').should("not.be.disabled");
  });

  // ── C7 — create success ─────────────────────────────────────────────────────
  it("creates a corpus, toasts, and lands on the new corpus", () => {
    const name = uniq("Corpus Create");
    visitFiles("/files/new");

    cy.findByLabelText("Name").type(name).blur();
    cy.get("form").find('button[type="submit"]').click();

    cy.findByTestId("toast-success").should("be.visible");
    cy.location("pathname").should("match", /\/files\/corpora\/[^/]+$/);
    // Register the UI-created corpus for teardown.
    cy.location("pathname").then((p) => {
      const id = p.split("/corpora/")[1];
      if (id) cleanup.push(id);
    });
  });

  // ── C8 — create failure ─────────────────────────────────────────────────────
  it("shows both an inline alert and an error toast on a failed create, staying on the form", () => {
    cy.intercept("POST", CORPORA_LIST, {
      statusCode: 500,
      body: {
        error: { code: "internal", message: "Simulated create failure" },
      },
    }).as("createCorpus");

    visitFiles("/files/new");
    cy.findByLabelText("Name").type(uniq("Doomed Corpus")).blur();
    cy.get("form").find('button[type="submit"]').click();
    cy.wait("@createCorpus");

    // Both surfaces fire, and the user stays on /files/new. Assert the toast
    // FIRST and by testid: the error toast auto-dismisses (~7s) and shares
    // role="alert" with the inline form error, so a role-based query would be
    // ambiguous while both are up. The inline alert is then scoped to the form
    // so it can only match the in-form error, never the (portalled) toast.
    cy.findByTestId("toast-error").should("be.visible");
    cy.get("form")
      .findByRole("alert")
      .should("contain.text", "Simulated create failure");
    cy.location("pathname").should("match", /\/files\/new$/);
  });

  // ── C9 — edit ───────────────────────────────────────────────────────────────
  it("edits a corpus name and visibility and reflects both changes on the row", () => {
    const original = uniq("Corpus Before");
    const renamed = uniq("Corpus After");
    bffCreateCorpus({ name: original, visibility: "PRIVATE" }).then((corpus) => {
      cleanup.push(corpus.id);
      visitFiles("/files");

      // C4 (edit half): opening Edit must not navigate off the list.
      corpusRow(original).find('[data-row-action="edit"]').click();
      cy.location("pathname").should("match", /\/files\/?$/);

      cy.findByRole("dialog").within(() => {
        cy.findByText("Edit Corpus").should("be.visible");
        cy.findByLabelText(/Name/).clear().type(renamed);
        cy.findByLabelText("Visibility").select("TEAM");
        cy.findByRole("button", { name: "Save changes" }).click();
      });

      cy.findByTestId("toast-success").should("be.visible");
      cy.findByRole("dialog").should("not.exist");

      // Round-trip: the list refetched — the row now carries the new name AND
      // the new pill, and the old name is gone.
      corpusRow(renamed).within(() => {
        cy.findByText("Team").should("be.visible");
      });
      cy.findByText(original).should("not.exist");
    });
  });

  // ── C10 + C11 + C12 — delete (type-to-confirm) ──────────────────────────────
  it("gates delete behind exact type-to-confirm, then removes the row", () => {
    const name = uniq("Corpus Delete");
    bffCreateCorpus({ name, visibility: "PRIVATE" }).then((corpus) => {
      cleanup.push(corpus.id);
      visitFiles("/files");

      corpusRow(name).find('[data-row-action="delete"]').click();

      cy.findByRole("alertdialog").within(() => {
        cy.findByText(`Delete corpus "${name}"`).should("be.visible");
        // C11: the live entity count resolves from the subgraph fetch.
        cy.findByText(/will be unlinked from this corpus/).should("be.visible");

        const confirm = () =>
          cy.findByRole("button", { name: "Delete corpus" });

        // C10: a near-miss (name minus its last char) keeps confirm disabled.
        cy.findByLabelText(/to confirm/i).type(name.slice(0, -1));
        confirm().should("be.disabled");

        // The exact name enables it.
        cy.findByLabelText(/to confirm/i)
          .clear()
          .type(name);
        confirm().should("not.be.disabled").click();
      });

      // C12: toast, and the row is gone from the list.
      cy.findByTestId("toast-success").should("be.visible");
      cy.findByText(name).should("not.exist");
    });
  });
});


