/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />
/**
 * files-bff raw file disposition (security plan Task 6).
 *
 * files-bff's `GET /api/v1/files/documents/{id}/raw` (documentH.GetRawFile)
 * sets `Content-Disposition: attachment` for every stored MIME type except
 * the fixed inline-safe raster set (image/png, jpeg, gif, webp, bmp), and
 * the upload guard (`POST /api/v1/files/corpora/{id}/documents`, sniffed via
 * platform/libs/go/security.ResolveUploadMIME + FilesUploadPolicy) rejects
 * image/svg+xml and text/html outright with 415 before anything ever
 * touches storage — see platform/libs/go/security/mime.go's alwaysRejected
 * map. This spec exercises both halves end to end through the real
 * files-mfe upload dropzone and the real files-bff, proxied through the
 * shell session cookie (no stubbing).
 *
 * Upload is driven through the actual `UploadDropzone` component (drag-drop,
 * mirroring frontends/cypress/cypress/e2e/studio/propaganda-analysis-document.cy.ts's
 * established pattern for exercising a real multipart POST without a native
 * OS file-picker dependency) rather than hand-built multipart bodies — this
 * runs the exact same client code path a real user's browser would.
 *
 * File contents are inlined (Cypress.Buffer / plain strings) rather than
 * checked-in fixtures, per this task's single-new-file constraint. The PNG
 * is a genuine 1x1 RGB PNG (real magic bytes + valid IDAT/IEND chunks) —
 * required because ResolveUploadMIME sniffs content, it does not trust the
 * declared Content-Type.
 *
 * Persona: P4 (plain org member), same as the rest of the suite's files-vertical
 * probes (studio/_helpers.ts's requireFilesUp).
 */

// A genuine 1x1 opaque-red PNG (signature + IHDR + IDAT + IEND, 69 bytes).
// ResolveUploadMIME sniffs via http.DetectContentType, so this must be real
// PNG bytes — a declared-but-fake Content-Type would 415.
const PNG_BASE64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGP4z8AAAAMBAQDJ/pLvAAAAAElFTkSuQmCC";

const TEXT_CONTENT =
  "Plain text content for the raw-file-disposition Cypress spec. Not an " +
  "image, so files-bff must serve it with Content-Disposition: attachment.";

const HTML_CONTENT =
  "<!doctype html>\n<html><body><script>alert(1)</script></body></html>\n";

const SVG_CONTENT =
  '<?xml version="1.0" encoding="UTF-8"?>\n' +
  '<svg xmlns="http://www.w3.org/2000/svg" onload="alert(1)">' +
  "<rect width=\"1\" height=\"1\"/></svg>\n";

interface CorporaResponse {
  data?: { corpora?: Array<{ id: string; is_personal_inbox?: boolean }> };
}

interface UploadResponse {
  data?: { document?: { id: string }; ingest_job_id?: string };
}

function uniqueName(label: string, ext: string): string {
  return `e2e-raw-disposition-${label}-${Date.now()}.${ext}`;
}

/**
 * Visit a files-mfe corpus's documents tab with the Paraglide locale pinned
 * to en-US — mirrors studio/_helpers.ts's visitStudio, scoped to this spec.
 */
function visitCorpusDocuments(corpusId: string): void {
  cy.visit(`/files/corpora/${corpusId}?tab=documents`, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
    },
  });
}

/**
 * Drive a real multipart upload through the actual UploadDropzone component
 * (drag-drop bypasses the <input accept> allowlist, which is exactly what
 * the rejected-type cases need to reach files-bff's own server-side guard
 * rather than being filtered out client-side by the OS picker). Returns the
 * intercepted POST response.
 */
function uploadViaDropzone(
  corpusId: string,
  file: Cypress.FileReferenceObject,
) {
  visitCorpusDocuments(corpusId);
  cy.intercept("POST", "**/api/v1/files/corpora/*/documents").as("uploadDoc");
  cy.get('[data-testid="upload-dropzone"]').selectFile(file, {
    action: "drag-drop",
  });
  return cy.wait("@uploadDoc");
}

describe("files: raw file disposition (Task 6)", () => {
  let corpusId: string | undefined;

  beforeEach(function () {
    cy.login("P4");

    // requireFilesUp equivalent (studio/_helpers.ts's pattern, reproduced
    // locally rather than cross-imported — this lane is single-owner): skip
    // when the files vertical is unreachable through the shell proxy, or
    // when this persona/org has no personal-inbox corpus yet to upload into.
    cy.request({
      url: "/api/v1/files/workspace/corpora",
      failOnStatusCode: false,
    }).then((res) => {
      if (res.status !== 200) {
        this.skip();
        return;
      }
      const corpora = (res.body as CorporaResponse).data?.corpora ?? [];
      const inbox = corpora.find((c) => c.is_personal_inbox === true);
      if (inbox === undefined) {
        this.skip();
        return;
      }
      corpusId = inbox.id;
    });
  });

  it("serves a non-image document with Content-Disposition: attachment", function () {
    uploadViaDropzone(corpusId as string, {
      contents: TEXT_CONTENT,
      fileName: uniqueName("attachment", "txt"),
      mimeType: "text/plain",
    }).then((interception) => {
      expect(interception.response?.statusCode).to.eq(201);
      const documentId = (interception.response?.body as UploadResponse).data
        ?.document?.id;
      expect(documentId, "uploaded document id").to.be.a("string");

      cy.request(`/api/v1/files/documents/${documentId}/raw`).then((raw) => {
        expect(raw.status).to.eq(200);
        expect(raw.headers["content-disposition"]).to.match(/^attachment\b/);
      });
    });
  });

  it("serves an uploaded PNG inline (no attachment disposition)", function () {
    uploadViaDropzone(corpusId as string, {
      contents: Cypress.Buffer.from(PNG_BASE64, "base64"),
      fileName: uniqueName("inline", "png"),
      mimeType: "image/png",
    }).then((interception) => {
      expect(interception.response?.statusCode).to.eq(201);
      const documentId = (interception.response?.body as UploadResponse).data
        ?.document?.id;
      expect(documentId, "uploaded document id").to.be.a("string");

      cy.request(`/api/v1/files/documents/${documentId}/raw`).then((raw) => {
        expect(raw.status).to.eq(200);
        expect(raw.headers["content-type"]).to.eq("image/png");
        expect(raw.headers["content-disposition"]).to.be.undefined;
      });
    });
  });

  it("rejects an HTML upload with 415 before it ever reaches storage", function () {
    uploadViaDropzone(corpusId as string, {
      contents: HTML_CONTENT,
      fileName: uniqueName("rejected", "html"),
      mimeType: "text/html",
    }).then((interception) => {
      expect(interception.response?.statusCode).to.eq(415);
      expect(
        (interception.response?.body as { error?: { code?: string } }).error
          ?.code,
      ).to.eq("unsupported_media_type");
    });
  });

  it("rejects an SVG upload with 415 before it ever reaches storage", function () {
    uploadViaDropzone(corpusId as string, {
      contents: SVG_CONTENT,
      fileName: uniqueName("rejected", "svg"),
      mimeType: "image/svg+xml",
    }).then((interception) => {
      expect(interception.response?.statusCode).to.eq(415);
      expect(
        (interception.response?.body as { error?: { code?: string } }).error
          ?.code,
      ).to.eq("unsupported_media_type");
    });
  });
});


