/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />

/**
 * Files — Trash, Restore & Purge (code-first journey; no Epic, shipped behavior
 * is the bar). Covers the single-persona (P2 org OWNER) behaviors of the Trash
 * route: empty state, listing a soft-deleted document, restore round-trip,
 * purge, and Empty Trash. The two-persona RBAC centrepiece (T6 — Purge offered
 * to an owner but not a plain member, and refused by the BFF) lives in the
 * sibling `trash-permissions.cy.ts` (mixing `cy.login` personas in one file is
 * how session caching bites).
 *
 * ⚠ STAGING-ONLY SURFACE. The whole route is behind `FILES_MFE_TRASH`, which is
 * ON in the local `make up` stack but OFF in production — so nothing here is
 * reachable by a real user today. The flag-off redirect (T13) needs a flag-off
 * build and is not exercised here.
 *
 * DOM traps this file navigates:
 *  - Documents are seeded by POSTing a multipart upload straight to the BFF
 *    (see `_helpers.ts` `bffUploadTextDocument` / `seedTrashedDocument`) and then
 *    trashing via the BFF — the UI dropzone is unreliable under Cypress, and the
 *    async ingest pipeline is irrelevant to soft-delete.
 *  - Each destructive action is a kebab `DropdownMenu` → `AlertDialog`, the
 *    combination that can permanently inert `<body>` under Cypress. Every test
 *    starts on a FRESH page load (its own corpus + visit), so no test performs a
 *    second kebab→dialog cycle on a page a previous one locked.
 *  - The org DB is shared and additive; a retried attempt re-runs `beforeEach`
 *    but not `afterEach`, so every test seeds its OWN corpus and never asserts an
 *    absolute trash count beyond what it put there.
 *
 * Deferred (see the journey): T3 chip-colour escalation (time-based, brittle),
 * T7/T8 orphan-preview (needs extracted entities), T10's skip-counts (need
 * orphan/permission-blocked entries), T12 move-to-Trash Undo (Documents
 * journey), T13 flag-off.
 */

import {
  bffCreateCorpus,
  bffDeleteCorpus,
  requireFilesUp,
  seedTrashedDocument,
  uniq,
  visitFiles,
} from "./_helpers";

/** A filesystem-safe unique document filename. */
function docName(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}.txt`;
}

/** Open a trash entry's kebab and yield the popup menu (portalled to body). */
function openEntryMenu(docId: string): void {
  cy.findByTestId(`trash-entry-${docId}`).within(() => {
    cy.findByRole("button", { name: "Trash entry options" }).click();
  });
}

describe("files: trash / restore / purge — owner (#files code-first)", () => {
  let cleanup: string[] = [];

  beforeEach(function () {
    cy.login("P2");
    requireFilesUp(this);
  });

  afterEach(() => {
    cleanup.forEach((id) => bffDeleteCorpus(id));
    cleanup = [];
  });

  // ── T4 — empty state ────────────────────────────────────────────────────────
  it("shows the empty state and a disabled Empty Trash button when the trash is empty", () => {
    bffCreateCorpus({ name: uniq("Trash Empty") }).then((corpus) => {
      cleanup.push(corpus.id);
      visitFiles(`/files/corpora/${corpus.id}/trash`);

      cy.findByText(
        "Trash is empty. Items here auto-delete after 30 days.",
      ).should("be.visible");
      cy.findByRole("button", { name: "Empty Trash" }).should("be.disabled");
    });
  });

  // ── T1 + T2 + T3(presence) — a trashed document is listed ────────────────────
  it("lists a soft-deleted document with an auto-purge chip and counts it on the sidebar badge", () => {
    bffCreateCorpus({ name: uniq("Trash Fill") }).then((corpus) => {
      cleanup.push(corpus.id);
      seedTrashedDocument(corpus.id, docName("trash-fill")).then((docId) => {
        visitFiles(`/files/corpora/${corpus.id}/trash`);

        cy.findByTestId(`trash-entry-${docId}`).should("be.visible");
        // T3 presence (not the colour escalation): the countdown chip renders.
        cy.findByTestId(`trash-entry-${docId}`)
          .findByTestId("auto-purge-chip")
          .should("exist");
        // With one entry, Empty Trash is now enabled, and the sidebar badge reads 1.
        cy.findByRole("button", { name: "Empty Trash" }).should(
          "not.be.disabled",
        );
        cy.findByTestId("trash-count-badge").should("contain.text", "1");
      });
    });
  });

  // ── T5 — restore round-trip ──────────────────────────────────────────────────
  it("restores a document back to the active documents list", () => {
    const fileName = docName("trash-restore");
    bffCreateCorpus({ name: uniq("Trash Restore") }).then((corpus) => {
      cleanup.push(corpus.id);
      seedTrashedDocument(corpus.id, fileName).then((docId) => {
        visitFiles(`/files/corpora/${corpus.id}/trash`);

        openEntryMenu(docId);
        cy.findByRole("menuitem", { name: "Restore" }).click();

        // Restore toasts the destination and drops the entry from the trash list.
        cy.findByTestId("toast-success").should("contain.text", "Restored to");
        cy.findByTestId(`trash-entry-${docId}`).should("not.exist");

        // Round-trip: the document is back on the active documents tab.
        visitFiles(`/files/corpora/${corpus.id}?tab=documents`);
        cy.findByText(fileName).should("be.visible");
      });
    });
  });

  // ── T9 — purge (owner can purge; no success toast) ──────────────────────────
  // PARKED on #2773: single-document purge through the UI is broken. Clicking
  // Purge fires POST …:preview-purge, which files-svc's PreviewDelete resolves
  // via the active-only GET_DOCUMENT (`deleted_at IS NULL`). But preview-purge
  // is only ever called on a TRASHED document (`deleted_at IS NOT NULL`), so the
  // lookup always 404s, TrashView.handlePurgeRequest's catch shows an error
  // toast, and the confirm modal never opens. (Bulk Empty Trash — T10 — works,
  // since it doesn't go through preview-purge.) Un-skip when #2773 lands.
  it.skip("purges a clean document, removing the entry with no success toast", () => {
    bffCreateCorpus({ name: uniq("Trash Purge") }).then((corpus) => {
      cleanup.push(corpus.id);
