/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />

/**
 * Files — oversized upload journey (#2754).
 *
 * The reported bug was that uploading a large file did NOTHING visible: no
 * toast, no failed row, no document, and the only evidence was a
 * `413 (Request Entity Too Large)` in the DevTools console. Two independent
 * defects produced that, and this spec covers the user-facing half of both:
 *
 *  1. The file is refused BEFORE the request, by the dropzone's own size guard,
 *     and the refusal is explained (it used to be uploaded in full and then
 *     rejected at the edge).
 *  2. A 413 that comes back from the wire — including nginx's own HTML error
 *     page, which is not the platform JSON envelope and used to make
 *     `JSON.parse` throw — renders as a size-specific message rather than
 *     `upload failed: 413`.
 *
 * The size-limit half of the fix (nginx `client_max_body_size` agreeing with
 * files-bff's `MaxUploadMB`) is pinned by `platform/scripts/upload-limit-lint.py`
 * and a files-bff handler test, not here: a browser journey cannot tell a 1 MB
 * edge cap from a 50 MB one without actually pushing 50 MB through CI.
 *
 * DOM traps this file navigates:
 *  - The dropzone's `<input type="file">` is `hidden`, so `selectFile` needs
 *    `{ force: true }` (the same reason `_helpers.ts` avoids the UI upload path
 *    for SEEDING — here the UI path IS the thing under test).
 *  - Toasts share `role="alert"` with the inline failed-upload reason, so a
 *    toast is always picked by `[data-testid="toast-error"]`.
 *  - The org DB is shared and additive: each test seeds its own corpus and
 *    asserts only on what it put there.
 */

import {
  bffCreateCorpus,
  bffDeleteCorpus,
  bffUploadTextDocument,
  requireFilesUp,
  uniq,
} from "./_helpers";

/**
 * Mirrors `MAX_UPLOAD_MB` in files-mfe and `defaultMaxUploadMB` in files-bff.
 * upload-limit-lint.py pins those two to each other; this copy exists only to
 * build a file on the wrong side of the line.
 */
const MAX_UPLOAD_MB = 50;
const MAX_UPLOAD_BYTES = MAX_UPLOAD_MB * 1024 * 1024;

/** en-US copy under test (see frontends/messages/en-US/files.json). */
const M = {
  too_large: (name: string) =>
    `“${name}” is too large. Maximum upload size is ${MAX_UPLOAD_MB} MB.`,
  failed_label: "Upload failed",
  dismiss_aria: "Dismiss failed upload",
} as const;

/**
 * Visit a corpus's Documents tab with the locale pinned for stable copy and
 * grid (tile) view pinned, so a seeded document is addressable by its own
 * `data-testid="doc-tile-<id>"` — the list view's DocumentCard carries no
 * per-document testid, and its visible text includes a raw corpus UUID, so
 * there is nothing stable to key off there.
 */
function visitDocs(corpusId: string): void {
  cy.visit(`/files/corpora/${corpusId}?tab=documents`, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
      win.localStorage.setItem("files-mfe.viewMode", "grid");
    },
  });
}

/** Drive the real dropzone, the way a user picking a file does. */
function pickFile(file: Cypress.FileReference): void {
  cy.get('input[type="file"]').selectFile(file, { force: true });
}

function smallTextFile(name: string): Cypress.FileReference {
  return {
    contents: Cypress.Buffer.from("a small document\n"),
    fileName: name,
    mimeType: "text/plain",
  };
}

describe("files: upload size limits (#2754)", () => {
  let cleanup: string[] = [];

  beforeEach(function () {
    cy.login("P2");
    requireFilesUp(this);
  });

  afterEach(() => {
    cleanup.forEach((id) => bffDeleteCorpus(id));
    cleanup = [];
  });

  // ── Defect 1+3: the client refuses an oversized file and says why ──────────
  it("refuses an over-limit file before sending it, and names the limit", () => {
    // Any upload POST at all is a failure here: the whole point of the guard is
    // that the user's upstream is not spent on a body the server will refuse.
    cy.intercept("POST", "**/api/v1/files/corpora/*/documents").as("upload");

    bffCreateCorpus({ name: uniq("Upload Limit") }).then((corpus) => {
      cleanup.push(corpus.id);
      visitDocs(corpus.id);
      cy.findByTestId("upload-dropzone").should("be.visible");

      pickFile({
        // One KiB past the cap: unambiguously over, without allocating more
        // than the limit itself.
        contents: Cypress.Buffer.alloc(MAX_UPLOAD_BYTES + 1024, 0),
        fileName: "oversized-report.pdf",
        mimeType: "application/pdf",
      });

      cy.findByTestId("toast-error").should(
        "contain.text",
        M.too_large("oversized-report.pdf"),
      );
      // The bare status code is exactly what the user used to be shown — and
      // only in the console. It must not appear in the message.
      cy.findByTestId("toast-error").should("not.contain.text", "413");

      // The toast auto-dismisses; the queue row is the durable record, and a
      // client-side refusal must leave one just like a server-side 413 does.
      cy.findByTestId("upload-failed")
        .should("contain.text", M.failed_label)
        .and("contain.text", M.too_large("oversized-report.pdf"));

      // Nothing was sent. cy.wait would pass on a request that arrived late, so
      // assert on the intercept's own call log instead.
      cy.get("@upload.all").should("have.length", 0);
    });
  });

  it("dismisses a client-refused file's row through its own control", () => {
    bffCreateCorpus({ name: uniq("Upload Client Dismiss") }).then((corpus) => {
      cleanup.push(corpus.id);
      visitDocs(corpus.id);
      cy.findByTestId("upload-dropzone").should("be.visible");

      pickFile({
        contents: Cypress.Buffer.alloc(MAX_UPLOAD_BYTES + 1024, 0),
        fileName: "oversized-report.pdf",
        mimeType: "application/pdf",
      });

      cy.findByTestId("upload-failed").should("be.visible");
      cy.findByTestId("upload-failed").within(() => {
        cy.findByRole("button", { name: M.dismiss_aria }).click();
      });
      cy.findByTestId("upload-failed").should("not.exist");
      cy.findByTestId("upload-queue").should("not.exist");
    });
  });

  it("leaves the document list untouched when an upload is refused", () => {
    const seeded = `kept-${Date.now()}.txt`;
    bffCreateCorpus({ name: uniq("Upload Limit List") }).then((corpus) => {
      cleanup.push(corpus.id);
      bffUploadTextDocument(corpus.id, seeded, "still here\n").then((docId) => {
        visitDocs(corpus.id);
        cy.findByTestId(`doc-tile-${docId}`).should("exist");

        pickFile({
          contents: Cypress.Buffer.alloc(MAX_UPLOAD_BYTES + 1024, 0),
          fileName: "oversized-report.pdf",
          mimeType: "application/pdf",
        });

        cy.findByTestId("toast-error").should("be.visible");
        // The seeded document survives, and the refused one never appears.
        cy.findByTestId(`doc-tile-${docId}`).should("exist");
        cy.findByText("oversized-report.pdf").should("not.exist");
      });
    });
  });

  // ── Defect 2+3: a 413 off the wire is rendered, and is dismissable ─────────
  it("renders nginx's non-JSON 413 as a size message, not a bare status code", () => {
    // This is the edge rejection itself: nginx answers with an HTML error page,
    // NOT the platform `{data, error}` envelope. Parsing it used to throw, and
    // the rejection degraded to the generic `upload failed: 413`.
    cy.intercept("POST", "**/api/v1/files/corpora/*/documents", {
      statusCode: 413,
      headers: { "content-type": "text/html" },
      body:
        "<html>\r\n<head><title>413 Request Entity Too Large</title></head>\r\n" +
        "<body>\r\n<center><h1>413 Request Entity Too Large</h1></center>\r\n" +
        "<hr><center>nginx</center>\r\n</body>\r\n</html>\r\n",
    }).as("upload");

    bffCreateCorpus({ name: uniq("Upload Edge 413") }).then((corpus) => {
      cleanup.push(corpus.id);
      visitDocs(corpus.id);
      cy.findByTestId("upload-dropzone").should("be.visible");

      pickFile(smallTextFile("edge-rejected.txt"));
      cy.wait("@upload");

      cy.findByTestId("toast-error").should(
        "contain.text",
        M.too_large("edge-rejected.txt"),
      );
      // The durable record, which outlives the toast's auto-dismiss.
      cy.findByTestId("upload-failed")
        .should("contain.text", M.failed_label)
        .and("contain.text", M.too_large("edge-rejected.txt"));
    });
  });

  it("dismisses the failed-upload entry through its own control", () => {
    cy.intercept("POST", "**/api/v1/files/corpora/*/documents", {
      statusCode: 413,
      headers: { "content-type": "text/html" },
      body: "<html><body><h1>413 Request Entity Too Large</h1></body></html>",
    }).as("upload");

    bffCreateCorpus({ name: uniq("Upload Dismiss") }).then((corpus) => {
      cleanup.push(corpus.id);
      visitDocs(corpus.id);
      cy.findByTestId("upload-dropzone").should("be.visible");

      pickFile(smallTextFile("dismiss-me.txt"));
      cy.wait("@upload");

      cy.findByTestId("upload-failed").should("be.visible");
      cy.findByTestId("upload-failed").within(() => {
        cy.findByRole("button", { name: M.dismiss_aria }).click();
      });
      cy.findByTestId("upload-failed").should("not.exist");
      cy.findByTestId("upload-queue").should("not.exist");
    });
  });
});



