/// <reference types="cypress" />

/**
 * Shared setup for the Files vertical Cypress specs.
 *
 * Files is a code-first vertical (no Epic) — shipped behavior is the bar. The
 * lone pre-existing spec (raw-file-disposition.cy.ts) is a single-owner
 * security probe that deliberately inlined its own setup; this module is the
 * reusable foundation for the behavior specs (corpus/document/folder/…) so each
 * seeds through the BFF and drives only the surface under test.
 *
 * Everything rides the shell session cookie: `cy.login(persona)` establishes it
 * and `cy.request` against the shell-proxied `/api/v1/files/*` routes carries it
 * automatically (same seam raw-file-disposition.cy.ts uses).
 */

const JSON_HEADERS = {
  "Content-Type": "application/json",
  Accept: "application/json",
} as const;

/** The BFF `{ data, error }` envelope, narrowed to the field we read. */
interface Envelope<T> {
  data?: T;
}

export interface SeededCorpus {
  id: string;
  name: string;
  visibility: "PRIVATE" | "TEAM";
  is_personal_inbox?: boolean;
}

/**
 * Visit a Files route with the Paraglide locale pinned to en-US, so the English
 * string assertions in the specs are stable regardless of the persona's or
 * browser's locale (mirrors range/_helpers.ts `visitRange`).
 */
export function visitFiles(path: string): void {
  cy.visit(path, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
    },
  });
}

/** A collision-proof name for a seeded object (the org DB is shared + additive). */
export function uniq(prefix: string): string {
  return `${prefix} ${Date.now()}-${Math.floor(Math.random() * 1000)}`;
}

/**
 * Guard the calling test on the Files vertical being reachable through the shell
 * proxy (the persona's org can see `/workspace/corpora`). Call from a
 * `function () {}` hook so `this` is the Mocha context:
 *
 *   beforeEach(function () { cy.login("P2"); requireFilesUp(this); });
 *
 * LOCALLY this skips when the vertical is down — a convenience so a files spec
 * doesn't drown a stackless run in failures. IN CI IT THROWS instead: the
 * files-cypress lane exists precisely to exercise files-bff, so a silent skip
 * would report green while testing nothing (the green-but-empty lane trap). Same
 * posture as `support/e2e.ts` `requireLiveStack()` and `ask/_helpers.ts`.
 */
export function requireFilesUp(ctx: Mocha.Context): void {
  cy.request({
    url: "/api/v1/files/workspace/corpora",
    failOnStatusCode: false,
  }).then((res) => {
    if (res.status === 200) return;
    if (Cypress.env("CI")) {
      throw new Error(
        `files vertical unreachable (/api/v1/files/workspace/corpora → ` +
          `${res.status}). In CI this is a failure, not a skip: the files-cypress ` +
          `lane exists to exercise files-bff, so skipping would report green ` +
          `while testing nothing.`,
      );
    }
    ctx.skip();
  });
}

/** Create a corpus through the BFF; yields the created corpus (with its id). */
export function bffCreateCorpus(body: {
  name: string;
  visibility?: "PRIVATE" | "TEAM";
  description?: string;
}): Cypress.Chainable<SeededCorpus> {
  return cy
    .request({
      method: "POST",
      url: "/api/v1/files/corpora",
      headers: JSON_HEADERS,
      body,
    })
    .then((res) => {
      expect(res.status, "create corpus status").to.be.oneOf([200, 201]);
      const corpus = (res.body as Envelope<SeededCorpus>).data;
      expect(corpus?.id, "created corpus id").to.be.a("string");
      return corpus as SeededCorpus;
    });
}

/**
 * Delete a corpus through the BFF. Defaults to not failing on a non-2xx so it is
 * safe as idempotent cleanup for a corpus a test may already have deleted.
 */
export function bffDeleteCorpus(
  id: string,
  failOnStatusCode = false,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "DELETE",
    url: `/api/v1/files/corpora/${id}`,
    headers: JSON_HEADERS,
    failOnStatusCode,
  });
}

// ---------------------------------------------------------------------------
// Documents & Trash
// ---------------------------------------------------------------------------

/**
 * Upload a plain-text document straight to the BFF as a multipart POST (the same
 * `POST /corpora/{id}/documents` with a single `file` part the app's
 * `uploadDocument` sends), and yield the created document's id.
 *
 * We POST directly rather than driving the `UploadDropzone`: this is SEEDING,
 * not an upload test, and the UI path proved unreliable under Cypress
 * (`selectFile` fought the dropzone's hidden `<input type="file">`, and the
 * drag-drop simulation never fired `handleDrop`). The multipart body is built by
 * hand because `cy.request` won't assemble one from an object; text content
 * keeps that trivial. No Idempotency-Key is sent — the BFF accepts cookie-authed
 * `cy.request` writes without one (see `bffCreateCorpus`).
 */
export function bffUploadTextDocument(
  corpusId: string,
  fileName: string,
  contents: string,
): Cypress.Chainable<string> {
  const boundary = `----omnicoreE2E${Date.now()}${Math.floor(
    Math.random() * 1e6,
  )}`;
  const body =
    `--${boundary}\r\n` +
    `Content-Disposition: form-data; name="file"; filename="${fileName}"\r\n` +
    `Content-Type: text/plain\r\n\r\n` +
    `${contents}\r\n` +
    `--${boundary}--\r\n`;
  return cy
    .request({
      method: "POST",
      url: `/api/v1/files/corpora/${corpusId}/documents`,
      headers: { "Content-Type": `multipart/form-data; boundary=${boundary}` },
      body,
    })
    .then((res) => {
      expect(res.status, "upload status").to.be.oneOf([200, 201]);
      const id = (res.body as { data?: { document?: { id: string } } }).data
        ?.document?.id;
      expect(id, "uploaded document id").to.be.a("string");
      return id as string;
    });
}

/** Soft-delete a document into its corpus's Trash (POST …:trash). */
export function bffTrashDocument(
  corpusId: string,
  docId: string,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "POST",
    url: `/api/v1/files/corpora/${corpusId}/documents/${docId}:trash`,
    headers: JSON_HEADERS,
  });
}

/** Permanently purge a trashed document (POST …:purge, `ResolveOrgRole`-gated). */
export function bffPurgeDocument(
  corpusId: string,
  docId: string,
  failOnStatusCode = false,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "POST",
    url: `/api/v1/files/corpora/${corpusId}/documents/${docId}:purge`,
    headers: JSON_HEADERS,
    failOnStatusCode,
  });
}

/**
 * Upload a plain-text document and immediately move it to Trash; yields the
 * document id. The one-stop setup for the Trash journey — the caller then drives
 * restore/purge/empty through the UI.
 */
export function seedTrashedDocument(
  corpusId: string,
  fileName: string,
): Cypress.Chainable<string> {
  return bffUploadTextDocument(
    corpusId,
    fileName,
    `Seed content for ${fileName}.\n`,
  ).then((docId) => bffTrashDocument(corpusId, docId).then(() => docId));
}


