/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />

/**
 * Files — Document Actions (code-first journey; no Epic, shipped behavior is the
 * bar). Covers the per-document kebab actions on the Documents tab: text Preview
 * (D10), Download (D12), Rename (D13), Copy (D14), and Move-to-Trash with a 5s
 * Undo (D16) — the last is the journey's highest-value assertion on this
 * surface. Move (D15, flag-gated) and all the folder actions live in a separate
 * `folders.cy.ts` (not yet written).
 *
 * Deferred from the preview slice: the PDF (<iframe>) and image (<img>) preview
 * renderers need real binary fixtures (the text-only BFF seed can't produce
 * them), and the HTML-sanitization path (D11, the #2424 mitigation) can't be
 * reached through a normal upload at all — files-bff's upload guard 415-rejects
 * text/html outright. Only the text → sanitized <pre> renderer is exercised.
 *
 * The document actions themselves (rename/copy/trash) are UNFLAGGED — they exist
 * on the card view too. This spec drives them through the DocumentTile kebab
 * (grid view), which needs `DOCUMENTS_TAB_V2` (on locally, off in prod), so it
 * pins `files-mfe.viewMode=grid` for a deterministic tile render.
 *
 * DOM traps this file navigates:
 *  - Documents are seeded straight through the BFF (`bffUploadTextDocument`) —
 *    no UI upload (see `_helpers.ts` for why the dropzone is unreliable under
 *    Cypress). Each doc is anchored by its `data-testid="doc-tile-<docId>"`,
 *    which is view- and title-agnostic (the tile shows `doc.title`, and the card
 *    meta even shows a raw corpus UUID — GAP-7 — so never key off displayed
 *    text).
 *  - The kebab menu is a plain inline `role="menu"` (not Radix), so no
 *    pointer-events lock; the Rename modal IS a Radix Dialog, but each test is a
 *    fresh page load, so no cross-test lock.
 *  - Toasts share `role="status"` with ingest badges — always pick a toast by
 *    `[data-testid="toast-success"]`, never by role.
 *  - The org DB is shared and additive; every test seeds its OWN corpus and
 *    never asserts an absolute document count beyond what it put there.
 */

import {
  bffCreateCorpus,
  bffDeleteCorpus,
  bffUploadTextDocument,
  requireFilesUp,
  uniq,
} from "./_helpers";

function docName(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}.txt`;
}

/** Visit a corpus's Documents tab, pinning locale + grid (tile) view. */
function visitDocs(corpusId: string): void {
  cy.visit(`/files/corpora/${corpusId}?tab=documents`, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
      win.localStorage.setItem("files-mfe.viewMode", "grid");
    },
  });
}

/** Open a document tile's kebab menu. */
function openDocMenu(docId: string): void {
  cy.findByTestId(`doc-tile-${docId}`).within(() => {
    cy.findByRole("button", { name: "Document options" }).click();
  });
}

/** Seed a fresh corpus with one text document; yields { corpusId, docId, name }. */
function seedCorpusWithDoc(
  corpusLabel: string,
  fileName: string,
): Cypress.Chainable<{ corpusId: string; docId: string }> {
  return bffCreateCorpus({ name: uniq(corpusLabel) }).then((corpus) =>
    bffUploadTextDocument(corpus.id, fileName, `Seed for ${fileName}.\n`).then(
      (docId) => ({ corpusId: corpus.id, docId }),
    ),
  );
}

describe("files: document actions (#files code-first)", () => {
  let cleanup: string[] = [];

  beforeEach(function () {
    cy.login("P2");
    requireFilesUp(this);
  });

  afterEach(() => {
    cleanup.forEach((id) => bffDeleteCorpus(id));
    cleanup = [];
  });

  // ── D10 — preview (text renderer) ───────────────────────────────────────────
  it("previews a text document as sanitized content in the modal", () => {
    const marker = `preview-marker-${Date.now()}`;
    const fileName = docName("preview");
    bffCreateCorpus({ name: uniq("Doc Preview") }).then((corpus) => {
      cleanup.push(corpus.id);
      bffUploadTextDocument(
        corpus.id,
        fileName,
        `This document contains ${marker} for the preview test.\n`,
      ).then((docId) => {
        visitDocs(corpus.id);

        cy.findByTestId(`doc-tile-${docId}`).should("be.visible");
        openDocMenu(docId);
        cy.findByRole("menuitem", { name: "Preview" }).click();

        // text/* routes to a <pre>; the fetched content renders verbatim.
        cy.findByRole("dialog").within(() => {
          cy.get("pre").should("contain.text", marker);
        });
      });
    });
  });

  // ── D12 — download ──────────────────────────────────────────────────────────
  it("downloads a document with disposition=attachment", () => {
    // Match only the attachment fetch — the inline preview fetch (no query)
    // must not satisfy this wait.
    cy.intercept(
      "GET",
      /\/api\/v1\/files\/documents\/[^/]+\/raw\?disposition=attachment/,
    ).as("download");

    seedCorpusWithDoc("Doc Download", docName("download")).then(
      ({ corpusId, docId }) => {
        cleanup.push(corpusId);
        visitDocs(corpusId);

        cy.findByTestId(`doc-tile-${docId}`).should("be.visible");
        openDocMenu(docId);
        cy.findByRole("menuitem", { name: "Download" }).click();

        // The download requests the raw bytes as an attachment (matched by the
        // intercept above — waiting proves the disposition query fired).
        cy.wait("@download");
      },
    );
  });

  // ── D13 — rename ────────────────────────────────────────────────────────────
  it("renames a document and sends the new filename to the server", () => {
    const renamed = docName("renamed");
    seedCorpusWithDoc("Doc Rename", docName("original")).then(
      ({ corpusId, docId }) => {
        cleanup.push(corpusId);
        visitDocs(corpusId);
        cy.intercept("POST", "**/api/v1/files/documents/*:rename").as("rename");

        cy.findByTestId(`doc-tile-${docId}`).should("be.visible");
        openDocMenu(docId);
        cy.findByRole("menuitem", { name: "Rename" }).click();
        cy.findByRole("dialog").within(() => {
          cy.findByLabelText("File name").clear().type(renamed);
          cy.findByRole("button", { name: "Save" }).click();
        });

        // Prove the seam: the rename request carried the new name...
        cy.wait("@rename")
          .its("request.body")
          .then((body) => {
            expect(JSON.stringify(body)).to.contain(renamed);
          });
        // ...and it succeeded (Renamed toast; only fires server-side-OK).
        cy.findByTestId("toast-success").should("be.visible");
      },
    );
  });

  // ── D14 — copy ──────────────────────────────────────────────────────────────
  it("copies a document, adding a second entry to the list", () => {
    seedCorpusWithDoc("Doc Copy", docName("copy-src")).then(
      ({ corpusId, docId }) => {
        cleanup.push(corpusId);
        visitDocs(corpusId);

        cy.findByTestId(`doc-tile-${docId}`).should("be.visible");
        openDocMenu(docId);
        cy.findByRole("menuitem", { name: "Copy" }).click();

        cy.findByTestId("toast-success").should("be.visible"); // "Copy created"
        // The list grew by one — two documents, so two kebabs.
        cy.findAllByRole("button", { name: "Document options" }).should(
          "have.length",
          2,
        );
      },
    );
  });

  // ── D16 — move to Trash + Undo (the round-trip) ─────────────────────────────
  it("moves a document to Trash and restores it via the Undo toast", () => {
    seedCorpusWithDoc("Doc Trash Undo", docName("trash-undo")).then(
      ({ corpusId, docId }) => {
        cleanup.push(corpusId);
        visitDocs(corpusId);

        cy.findByTestId(`doc-tile-${docId}`).should("be.visible");
        openDocMenu(docId);
        cy.findByRole("menuitem", { name: "Delete" }).click();

        // Row gone, and the toast offers Undo.
        cy.findByTestId(`doc-tile-${docId}`).should("not.exist");
        cy.findByTestId("toast-success")
          .should("contain.text", "Moved to Trash")
          .findByRole("button", { name: "Undo" })
          .click();

        // The Undo restores the document to the active list (same id returns).
        cy.findByTestId(`doc-tile-${docId}`).should("be.visible");
      },
    );
  });
});


