/// <reference types="cypress" />

/**
 * Files — known-type import recognition (issue #256).
 *
 * Journey: a user uploads an externally authored export into a corpus; the
 * ingest worker recognises its CONTENT as a platform domain object; the
 * document list badges it and offers a link into the vertical that owns it.
 *
 * This is the one place the whole chain is exercised end to end — worker
 * detection, the known_type column, the BFF passthrough, and the badge. The
 * unit suites pin each link in isolation; only this proves they meet.
 *
 * Two deliberate choices worth knowing before editing:
 *
 * 1. The spec waits for `known_type` to appear, NOT for `ingest_status` to
 *    reach "complete". Detection happens in the worker's PARSE phase and
 *    commits with the parsed chunks, so the classification is durable long
 *    before embedding and extraction finish. Waiting on "complete" would
 *    couple this spec to LiteLLM/Qdrant availability for no added signal.
 *
 * 2. The envelopes are uploaded as `text/plain` (what the shared helper
 *    sends), not as `application/json`. That is the point: classification
 *    reads bytes, so a mislabelled or generically-labelled upload must still
 *    be recognised. A spec that uploaded them as application/json would pass
 *    even if detection regressed to trusting the declared MIME.
 */

import {
  bffCreateCorpus,
  bffDeleteCorpus,
  bffUploadTextDocument,
  requireFilesUp,
  uniq,
} from "./_helpers";

/**
 * Visit a corpus's Documents tab.
 *
 * `?tab=documents` is required — the corpus route opens on a different tab
 * and the document list is not mounted without it.
 *
 * The view mode is deliberately NOT pinned, unlike document-actions.cy.ts
 * which forces "grid". `useViewMode` defaults to grid, so leaving it unset
 * exercises what a user who has never touched the view toggle actually sees.
 * Both modes must carry the badge; the two runs below cover each explicitly.
 */
function visitDocs(corpusId: string, viewMode?: "grid" | "list"): void {
  cy.visit(`/files/corpora/${corpusId}?tab=documents`, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
      if (viewMode) win.localStorage.setItem("files-mfe.viewMode", viewMode);
    },
  });
}

/**
 * How long to give the ingest worker to pick up the job and classify it.
 *
 * Generous for a reason that is NOT detection speed: classification itself
 * lands in ~200ms, during the parse phase. The budget is for HEAD-OF-LINE
 * BLOCKING. The worker consumes its JetStream queue serially, and every
 * files ingest job currently spends 60s in the embedding phase before
 * failing — `files_svc.worker.embedding` calls LiteLLM directly with a
 * hardcoded `timeout=60.0` and has no AI_TEST_MODE/StubLLM path, so `STUB=1`
 * does not stub it. A document uploaded third therefore waits behind two
 * 60s timeouts before its own parse even starts.
 *
 * This spec deliberately tolerates that instead of working around it: the
 * classification is committed in the parse transaction and survives the
 * later embedding failure, which is precisely the property that makes
 * waiting on `known_type` (not on `ingest_status === "complete"`) correct.
 * If the embedding path is ever fixed or stubbed, this only gets faster.
 */
const CLASSIFY_TIMEOUT_MS = 180_000;
const POLL_INTERVAL_MS = 1_000;

interface ListedDocument {
  id: string;
  filename: string;
  known_type?: string;
}

function envelope(omnicoreType: string, payload: Record<string, unknown>): string {
  return JSON.stringify(
    { omnicore_type: omnicoreType, schema_version: 1, payload },
    null,
    2,
  );
}

/**
 * Poll the corpus document list until `docId` carries a known_type, and yield
 * it. Fails the test with a readable message on timeout rather than leaving a
 * bare Cypress retry error, because "the worker never classified it" and "the
 * worker never ran at all" look identical from the assertion alone.
 */
function waitForKnownType(
  corpusId: string,
  docId: string,
  deadline = Date.now() + CLASSIFY_TIMEOUT_MS,
): Cypress.Chainable<string> {
  return cy
    .request({ url: `/api/v1/files/corpora/${corpusId}/documents`, log: false })
    .then((res) => {
      const docs = (res.body as { data?: { documents?: ListedDocument[] } }).data
        ?.documents;
      const found = docs?.find((d) => d.id === docId);
      if (found?.known_type) return cy.wrap(found.known_type, { log: false });
      if (Date.now() > deadline) {
        throw new Error(
          `document ${docId} still has no known_type after ` +
            `${CLASSIFY_TIMEOUT_MS}ms. Either the ingest worker is not running, ` +
            `detection did not recognise the envelope, or the worker is still ` +
            `draining earlier jobs (see CLASSIFY_TIMEOUT_MS above — each queued ` +
            `document costs up to 60s in the embedding phase). ` +
            `Check \`docker logs <stack>-files-svc-worker-1\` for a ` +
            `"parsed ... known_type=" line. Current row: ` +
            `${JSON.stringify(found ?? null)}`,
        );
      }
      // eslint-disable-next-line cypress/no-unnecessary-waiting -- polling an
      // asynchronous worker; there is no request to cy.wait() on an alias for.
      cy.wait(POLL_INTERVAL_MS, { log: false });
      return waitForKnownType(corpusId, docId, deadline);
    });
}

describe("Files — known-type import", () => {
  let corpusId: string;

  beforeEach(function () {
    cy.login("P2");
    requireFilesUp(this);
    bffCreateCorpus({ name: uniq("Known types"), visibility: "TEAM" }).then((c) => {
      corpusId = c.id;
    });
  });

  afterEach(() => {
    if (corpusId) bffDeleteCorpus(corpusId);
  });

  it("recognises an audience profile and offers the Studio handoff", () => {
    const filename = "lapsed-holders.json";
    bffUploadTextDocument(
      corpusId,
      filename,
      envelope("audience_profile", {
        audience_name: "Lapsed Season-Ticket Holders",
        audience_summary: "Former subscribers who did not renew.",
        demographics: { age_range: "35-54" },
      }),
    ).then((docId) => {
      waitForKnownType(corpusId, docId).should("eq", "audience_profile");

