        scenario_context: "A regional utility outage escalates over 72 hours.",
      }),
    ).then((docId) => {
      waitForKnownType(corpusId, docId).should("eq", "exercise");

      visitDocs(corpusId);
      cy.contains("Exercise").should("be.visible");
      cy.findByRole("link", { name: `Open ${filename} in Range` })
        .should("have.attr", "href")
        .and("include", "/range/exercises/new");
    });
  });

  it("offers the handoff in list mode too, not just the default grid", () => {
    // The badge lives in two components — DocumentTile (grid, the DEFAULT)
    // and DocumentCard (list) — because the Documents tab renders one or the
    // other from `files-mfe.viewMode`. Shipping it in only one is invisible
