/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />

/**
 * Files — Trash purge permissions (T6): the one genuine, backend-enforced RBAC
 * seam in the whole vertical. Purge / list-trash / empty-trash are wrapped in
 * files-bff's `ResolveOrgRole`, which forwards the caller's org-membership role
 * (OWNER/ADMIN) so files-svc can gate an admin override — acting on *any* user's
 * trashed documents rather than only your own. The per-entry `caller_can_purge`
 * boolean is the UI's read of that gate and drives whether Purge appears in an
 * entry's kebab. Unlike `useCapabilities` (GAP-11, grants everything), THIS is
 * real — so it's the strongest permission assertion in Files.
 *
 * The pairing under test: as the org OWNER who trashed a document, Purge is
 * offered; as a plain MEMBER viewing a document the owner trashed, Purge is
 * absent from the kebab AND the BFF refuses a direct purge. The server-refusal
 * half is the load-bearing one — a UI-only assertion still passes if the server
 * stops enforcing.
 *
 * Personas: P2 (org OWNER) seeds and owns the corpus/document; P4 (plain
 * MEMBER, same org) is the unauthorized caller. The corpus is TEAM-visible so
 * P4 can see it at all. STAGING-ONLY surface (`FILES_MFE_TRASH`, off in prod).
 *
 * ⚠ Highest-uncertainty spec in the Files set: it assumes a same-org MEMBER can
 * SEE another member's trashed entry in the list (the #1806 visibility area). If
 * that assumption is wrong the P4 anchor assertion fails loudly (by design) —
 * the server-refusal check below it does not depend on the UI and stands either
 * way.
 */

import {
  bffCreateCorpus,
  bffDeleteCorpus,
  bffPurgeDocument,
  requireFilesUp,
  seedTrashedDocument,
  uniq,
  visitFiles,
} from "./_helpers";

function docName(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}.txt`;
}

function openEntryMenu(docId: string): void {
  cy.findByTestId(`trash-entry-${docId}`).within(() => {
    cy.findByRole("button", { name: "Trash entry options" }).click();
  });
}

describe("files: trash purge permissions — owner vs member (#files code-first)", () => {
  let cleanup: string[] = [];

  beforeEach(function () {
    cy.login("P2");
    requireFilesUp(this);
  });

  afterEach(() => {
    // Delete as the OWNER — a member can't delete the corpus.
    cy.login("P2");
    cleanup.forEach((id) => bffDeleteCorpus(id));
    cleanup = [];
  });

  it("offers Purge to the org owner who trashed the document", () => {
    bffCreateCorpus({ name: uniq("Trash Perm Owner"), visibility: "TEAM" }).then(
      (corpus) => {
        cleanup.push(corpus.id);
        seedTrashedDocument(corpus.id, docName("perm-owner")).then((docId) => {
          visitFiles(`/files/corpora/${corpus.id}/trash`);

          cy.findByTestId(`trash-entry-${docId}`).should("be.visible");
          openEntryMenu(docId);
          cy.findByRole("menuitem", { name: "Purge" }).should("exist");
        });
      },
    );
  });

  it("hides Purge from a plain member and the BFF refuses their direct purge", () => {
    bffCreateCorpus({
      name: uniq("Trash Perm Member"),
      visibility: "TEAM",
    }).then((corpus) => {
      cleanup.push(corpus.id);
      // Seed as the OWNER (P2): a document THIS member did not trash.
      seedTrashedDocument(corpus.id, docName("perm-member")).then((docId) => {
        // Switch to the plain member.
        cy.login("P4");

        // The member can see the entry, and its kebab offers Restore but NOT
        // Purge (caller_can_purge is false for a non-owner who didn't trash it).
        visitFiles(`/files/corpora/${corpus.id}/trash`);
        cy.findByTestId(`trash-entry-${docId}`).should("be.visible");
        openEntryMenu(docId);
        cy.findByRole("menuitem", { name: "Restore" }).should("exist");
        cy.findByRole("menuitem", { name: "Purge" }).should("not.exist");

        // The load-bearing half: the BFF itself refuses a direct purge from the
        // member (DOM-independent — the enforcement, not just the affordance).
        bffPurgeDocument(corpus.id, docId, false).then((res) => {
          expect(res.status, "member purge refused").to.be.gte(400);
        });
      });
    });
  });
});


