  it("restores a document back to the active documents list", () => {
    const fileName = docName("trash-restore");
    bffCreateCorpus({ name: uniq("Trash Restore") }).then((corpus) => {
      cleanup.push(corpus.id);
      seedTrashedDocument(corpus.id, fileName).then((docId) => {
        visitFiles(`/files/corpora/${corpus.id}/trash`);

        openEntryMenu(docId);
        cy.findByRole("menuitem", { name: "Restore" }).click();

