        visitFiles(`/files/corpora/${corpus.id}/trash`);

        openEntryMenu(docId);
        cy.findByRole("menuitem", { name: "Purge" }).click();

        // A clean doc still previews first, opening the confirm dialog.
        cy.findByRole("alertdialog").within(() => {
          cy.findByText("Purge document").should("be.visible");
          cy.findByRole("button", { name: "Confirm" }).click();
        });

        // Entry gone — and, per the shipped (inconsistent) behavior, NO success
