        cy.findByTestId(`trash-entry-${docId}`).should("not.exist");
        cy.findByTestId("toast-success").should("not.exist");
      });
    });
  });

  // ── T10 — Empty Trash ────────────────────────────────────────────────────────
  it("empties the trash and reports the purged count", () => {
    bffCreateCorpus({ name: uniq("Trash Empty All") }).then((corpus) => {
      cleanup.push(corpus.id);
      seedTrashedDocument(corpus.id, docName("trash-empty")).then((docId) => {
        visitFiles(`/files/corpora/${corpus.id}/trash`);

        cy.findByRole("button", { name: "Empty Trash" }).click();
        cy.findByRole("alertdialog").within(() => {
          cy.findByRole("button", { name: "Confirm" }).click();
        });

        cy.findByTestId("toast-success").should("contain.text", "Emptied trash:");
        cy.findByTestId(`trash-entry-${docId}`).should("not.exist");
